import React from "react";
import { FaRegClock, FaChevronDown, FaFileAlt } from "react-icons/fa";

const API_URL = "https://iranaserviceapp.ir/test/api";

const PERSIAN_MONTHS = [
  "فروردین",
  "اردیبهشت",
  "خرداد",
  "تیر",
  "مرداد",
  "شهریور",
  "مهر",
  "آبان",
  "آذر",
  "دی",
  "بهمن",
  "اسفند",
];

class RequestsReportForm extends React.Component {
  constructor(props) {
    super(props);

    this.state = {
      year: "",
      month: "",
      outputFile: "excel",
      loading: false,
    };

    this.handleYearChange = this.handleYearChange.bind(this);
    this.handleMonthChange = this.handleMonthChange.bind(this);
    this.handleFileChange = this.handleFileChange.bind(this);
    this.handleSubmit = this.handleSubmit.bind(this);
  }

  handleYearChange(e) {
    this.setState({
      year: e.target.value,
    });
  }

  handleMonthChange(e) {
    this.setState({
      month: e.target.value,
    });
  }

  handleFileChange(e) {
    this.setState({
      outputFile: e.target.value,
    });
  }

  handleSubmit(e) {
    e.preventDefault();

    const { year, month, outputFile } = this.state;

    if (!year || !month) {
      alert("لطفاً سال و ماه را انتخاب کنید.");
      return;
    }

    if (outputFile !== "excel") {
      alert("در حال حاضر فقط خروجی Excel فعال است.");
      return;
    }

    const token = localStorage.getItem("token");

    /*
     * ماه انتخابی:
     * 1 = فروردین
     * 2 = اردیبهشت
     * ...
     * 12 = اسفند
     */

    const paddedMonth = String(month).padStart(2, "0");

    // شروع ماه
    const start = `${year}-${paddedMonth}-01`;

    /*
     * برای پایان ماه شمسی، فعلاً روز 31 ارسال می‌شود.
     * اگر API با تاریخ شمسی کار می‌کند، این مقدار باید متناسب
     * با ماه اصلاح شود.
     */
    let lastDay = 31;

    if (Number(month) <= 6) {
      lastDay = 31;
    } else if (Number(month) <= 11) {
      lastDay = 30;
    } else {
      lastDay = 30;
    }

    const end = `${year}-${paddedMonth}-${lastDay}`;

    this.setState({
      loading: true,
    });

    fetch(`${API_URL}/excel?`, {
      method: "GET",

      headers: {
        "Content-Type": "application/json",
        Accept: "*/*",
        Authorization: `Bearer ${token}`,
      },

      body: JSON.stringify({
        start: start,
        end: end,
      }),
    })
      .then((response) => {
        if (!response.ok) {
          throw new Error("خطا در دریافت فایل گزارش");
        }

        return response.blob();
      })
      .then((blob) => {
        /*
         * ساخت لینک موقت برای فایل
         */
        const url = window.URL.createObjectURL(blob);

        const link = document.createElement("a");

        link.href = url;
        link.download = `requests-${year}-${paddedMonth}.xlsx`;

        document.body.appendChild(link);

        link.click();

        link.remove();

        window.URL.revokeObjectURL(url);

        this.setState({
          loading: false,
        });
      })
      .catch((error) => {
        console.error("EXCEL ERROR:", error);

        this.setState({
          loading: false,
        });

        alert("دریافت فایل گزارش با خطا مواجه شد.");
      });
  }

  render() {
    const {
      year,
      month,
      outputFile,
      loading,
    } = this.state;

    return (
      <div>
        <div className="container px-3 pt-4 pb-5">

          <h1 className="fs-6 fw-semibold text-dark text-center mb-4">
            گزارش درخواست ها
          </h1>

          <form onSubmit={this.handleSubmit}>

            {/* سال */}
            <div className="d-flex align-items-center justify-content-between gap-2 border rounded-3 px-3 py-3 mb-3 bg-white">

              <FaRegClock
                className="text-secondary"
                size={18}
              />

              <input
                type="text"
                inputMode="numeric"
                placeholder="سال (مثال 1401)"
                value={year}
                onChange={this.handleYearChange}
                className="form-control border-0 shadow-none text-end p-0"
              />

            </div>

            {/* ماه */}
            <div className="d-flex align-items-center justify-content-between gap-2 border rounded-3 px-3 py-3 mb-3 bg-white">

              <FaRegClock
                className="text-secondary"
                size={18}
              />

              <select
                value={month}
                onChange={this.handleMonthChange}
                className="form-select border-0 bg-transparent text-end shadow-none flex-grow-1"
              >
                <option value="">
                  ماه
                </option>

                {PERSIAN_MONTHS.map((m, idx) => (
                  <option
                    key={m}
                    value={idx + 1}
                  >
                    {m}
                  </option>
                ))}
              </select>

              <FaChevronDown
                className="text-secondary"
                size={12}
              />

            </div>

            {/* فایل خروجی */}
            <div className="d-flex align-items-center justify-content-between gap-2 border rounded-3 px-3 py-3 mb-4 bg-white">

              <FaFileAlt
                className="text-secondary"
                size={18}
              />

              <select
                value={outputFile}
                onChange={this.handleFileChange}
                className="form-select border-0 bg-transparent text-end shadow-none flex-grow-1"
              >
                <option value="">
                  انتخاب فایل خروجی...
                </option>

                <option value="excel">
                  Excel
                </option>

                <option value="pdf">
                  PDF
                </option>

                <option value="csv">
                  CSV
                </option>
              </select>

            </div>

            {/* دکمه */}
            <button
              type="submit"
              disabled={loading}
              className="btn btn-primary w-100 rounded-3 py-3"
              style={{
                transition: "opacity 0.15s ease",
              }}
            >
              {loading
                ? "در حال دریافت فایل..."
                : "دریافت گزارش"}
            </button>

          </form>
        </div>
      </div>
    );
  }
}

export default RequestsReportForm;
